import UserEditIcon from '@/components/icons/user/UserEditIcon';
import { Dialog, DialogContent, DialogHeader } from '@/components/ui/dialog';
import { cn } from '@/lib/utils';
import AddAllowanceForm from '../../forms/addAllowance/AddAllowance';


interface Props {
    open: boolean;
    setAddAllowance: (value: boolean) => void;
    onCreated?: () => void | Promise<void>;
}

export default function AddAllowance({ open, setAddAllowance, onCreated }: Props) {
    return (
        <Dialog open={open}>
            <div
                className={cn('fixed inset-0 bg-black/50', {
                    '!hidden': !open,
                })}
            />
            <DialogContent
                showCloseButton={false}
                className="md:max-w-[623px] max-w-[90%] rounded-lg p-8 bg-white-blue-50 font-cairo gap-0 [&_[aria-label=Close]]:opacity-0"
            >
                <DialogHeader className="flex flex-col items-center">
                    <div className="flex flex-row justify-between mb-4 w-full">
                        <div className="flex flex-row gap-2">
                            <UserEditIcon />
                            <h3 className="text-[22px] font-bold text-primery-blue-500">
                                اضافة بدل
                                </h3>
                        </div>
                       
                    </div>
                    <div className="w-full border-b border-[#D1D1D1] !mt-0"></div>
                </DialogHeader>
                <AddAllowanceForm setAddAllowance={setAddAllowance} onCreated={onCreated} />
            </DialogContent>
        </Dialog>
    );
}
