import { Form } from '@/components/ui/form';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { apiGet, apiPost } from '@/lib/axios/axios-utils';
import { endpoints } from '@/lib/axios/axios-global';
import { useEffect, useMemo, useState } from 'react';
import { Employee } from '@/types/employee.types';
import { format } from 'date-fns';
import { SecondaryButton } from '@/components/buttons/SecondaryButton';
import { PrimaryButton } from '@/components/buttons/PrimaryButton';
import SearchableSelectInputForm from '@/components/forms/SearchableSelectInputForm';
import SelectInputForm from '@/components/forms/SelectInputForm';
import { toast } from 'sonner';
import TextInputForm from '@/components/forms/TextInputForm';
import { AddAllowanceFormValues, AddAllowanceSchema } from '../schemas/addAllowance/add-allowance-schema';
import MultipleReasonsInput from '@/components/forms/MultipleReasonsInput';

interface Props {
    employee?: Employee | null;
    setAddAllowance: (value: boolean) => void;
    /** Called after a successful create/update so parent tables can refetch */
    onCreated?: () => void | Promise<void>;
}

export default function AddAllowanceForm({ employee, setAddAllowance, onCreated }: Props) {
    const [error, setError] = useState<string | null>(null);
    const [loading, setLoading] = useState(false);
    const [employees, setEmployees] = useState<{ name: string; value: string }[]>([]);
    const [employeesError, setEmployeesError] = useState<string | null>(null);
    const [reasonInput, setReasonInput] = useState('');
    const [reasons, setReasons] = useState<string[]>([]);

    const defaultValues = useMemo(
        () => ({
            employee_id: '',
            name: '',
            amount: '',
            currency: 'sar',
            date: new Date(),
            allowance_type: 'allowances',
            status: 'approved',
        }),
        [employee],
    );

    const form = useForm<AddAllowanceFormValues>({
        resolver: zodResolver(AddAllowanceSchema),
        defaultValues,
    });

    const onSubmit = async (data: AddAllowanceFormValues) => {
        setLoading(true);
        setError(null); // Clear previous errors
        const normalizedReasons = reasons.map((r) => r.trim()).filter(Boolean);
        const formatedData = {
            ...data,
            amount: Number(data.amount),
            employee_id: Number(data.employee_id),
            date: format(data.date ?? new Date(), 'yyyy-MM-dd'),
            allowance_type: data.allowance_type || 'allowances',
            status: data.status || 'approved',
            currency: data.currency || 'sar',
            description: normalizedReasons.join('، '),
        };
        try {
            await apiPost({
                endpoint: employee ? endpoints.allowance.update + employee.id : endpoints.allowance.create,
                body: formatedData,
            });

            try {
                const selected = employees.find((e) => e.value === String(data.employee_id));
                if (selected) {
                    localStorage.setItem('hr:lastAllowanceEmployeeId', String(data.employee_id));
                    localStorage.setItem('hr:lastAllowanceEmployeeName', selected.name);
                } else {
                    localStorage.setItem('hr:lastAllowanceEmployeeId', String(data.employee_id));
                }
            } catch {
                // ignore localStorage failures
            }

            await onCreated?.();
            toast('تم اضافة البدل بنجاح');
            setReasons([]);
            setReasonInput('');
            form.reset(defaultValues);
            setAddAllowance(false);
        } catch (error: any) {
            if (error.response?.data?.errors) {
                // Handle field-specific errors
                Object.entries(error.response.data.errors).forEach(([field, messages]) => {
                    form.setError(field as any, {
                        type: 'manual',
                        message: (messages as string[]).join(', '),
                    });
                });
            } else {
                // Handle generic error
                let errorMessage = 'حدث خطأ أثناء إرسال البيانات. يرجى المحاولة مرة أخرى.';
                if (error.response) {
                    errorMessage = error.response.data.msg || errorMessage;
                } else if (error.request) {
                    errorMessage = 'تعذر الاتصال بالخادم. يرجى التحقق من اتصالك بالإنترنت.';
                }
                setError(errorMessage);
            }
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        const fetchEmployees = async () => {
            try {
                const response = await apiGet({ endpoint: endpoints.employee.simpleList });
                const options = (response.data.data as Employee[]).map((employee: Employee) => {
                    return { name: employee.name, value: String(employee.id) };
                });
                setEmployees(options);
                setEmployeesError(null);
            } catch (error) {
                setEmployeesError('Error fetching employees. Please try again later.');
            }
        };

        fetchEmployees();
    }, []);

    const addReason = () => {
        const value = reasonInput.trim();
        if (!value) return;
        setReasons((prev) => [...prev, value]);
        setReasonInput('');
    };

    const removeReason = (indexToRemove: number) => {
        setReasons((prev) => prev.filter((_, index) => index !== indexToRemove));
    };

    return (
        <>
            <Form {...form}>
                <form onSubmit={form.handleSubmit(onSubmit)} className="mt-6">
                    {error && (
                        <div className="mb-4 p-4 bg-red-100 border border-red-400 text-red-700 rounded-lg">
                            <div className="flex justify-between items-center">
                                <span className="">{error}</span>
                                <button onClick={() => setError(null)} className="text-red-700 hover:text-red-900">
                                    ×
                                </button>
                            </div>
                        </div>
                    )}
                    <div className="grid sm:grid-cols-2 grid-cols-1 gap-4 ">
                        <TextInputForm name="name" label=" البدل" placeholder="نوع البدل - تامينات - س  اعات اضافية" />

                        <TextInputForm name="amount" type="number" label="قيمة" placeholder="300" />
                        {/* <TextInputForm name="status" label="الحالة" placeholder="ادخل الحالة" /> */}
                        <SearchableSelectInputForm
                            name="employee_id"
                            placeholder="بحث عن اسم أو كود العميل"
                            label="اسم العميل"
                            options={employees}
                            error={employeesError}
                            data={true}
                        />
                        <SelectInputForm
                            name="currency"
                            label="العملة"
                            options={[
                                { name: 'ريال سعودي', value: 'sar' },

                                { name: 'جنيه مصري', value: 'egp' },
                                { name: 'دينار موريتاني', value: 'mr' },
                            ]}
                            placeholder="العملة"
                        />

                        <MultipleReasonsInput
                            label="اسباب البدل"
                            placeholder="اكتب سبب البدل"
                            value={reasonInput}
                            onValueChange={setReasonInput}
                            reasons={reasons}
                            onAddReason={addReason}
                            onRemoveReason={removeReason}
                        />
                    </div>
                    <div className="flex flex-row gap-4 mt-12">
                        <SecondaryButton
                            onClick={() => setAddAllowance(false)}
                            type="button"
                            className="w-full text-base leading-5 tracking-normal py-[10px] font-medium"
                        >
                            إلغاء
                        </SecondaryButton>
                        <PrimaryButton
                            type="submit"
                            className="w-full text-base leading-5 tracking-normal font-medium py-[10px]"
                        >
                            {loading ? 'جاري الحفظ...' : 'حفظ'}
                        </PrimaryButton>
                    </div>
                </form>
            </Form>
        </>
    );
}
